```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
struct rule
{
    char *target;
    struct rule *next;
};

struct rule *rule_new(const char *target)
{
    struct rule *r = calloc(1, sizeof(*r));
    if (!r)
        return NULL;
    r->target = strdup(target);
    return r;
