exos.sol:
```c
#include <ctype.h>

int count_deps(const char *s)
{
    int n = 0;
    while (*s)
    {
        while (isblank(*s))
            s++;
        if (!*s)
            break;
        n++;
        while (*s && !isblank(*s))
            s++;
    }
    return n;
}
```

