exos.enonce:
Écrire `char *expand(const char *s, struct var *vars)` : renvoie une nouvelle chaîne où chaque `${NOM}` est remplacé par sa valeur (chaîne vide si inconnue). On suppose les `}` présents. Allouer assez grand.

Ce `main` doit afficher :

```
[gcc -c main.c x]
```

```c
int main(void)
{
    struct var b = { "SRC", "main.c", NULL };
    struct var a = { "CC", "gcc", &b };
    char *r = expand("${CC} -c ${SRC} ${NOPE}x", &a);
    printf("[%s]\n", r);
    free(r);
    return 0;
}
```

exos.sol:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
struct var
{
    char *name;
    char *value;
    struct var *next;
};

static const char *lookup(struct var *v, const char *name, size_t len)
{
    for (; v; v = v->next)
        if (strlen(v->name) == len && !strncmp(v->name, name, len))
            return v->value;
    return "";
}

char *expand(const char *s, struct var *vars)
{
    size_t cap = strlen(s) + 1, n = 0;
    char *out = malloc(cap);
    while (*s)
    {
        const char *val = NULL;
        size_t vlen = 1;
        if (s[0] == '$' && s[1] == '{')
        {
            const char *end = strchr(s + 2, '}');
            val = lookup(vars, s + 2, end - (s + 2));
            vlen = strlen(val);
            s = end + 1;
        }
        if (n + vlen + 1 > cap)
        {
            cap = 2 * (n + vlen + 1);
            out = realloc(out, cap);
        }
        if (val)
        {
            memcpy(out + n, val, vlen);
            n += vlen;
        }
        else
            out[n++] = *s++;
    }
    out[n] = '\0';
    return out;
}
```

La valeur peut être plus longue que `${NOM}` : on agrandit le tampon (`realloc`). Variable inconnue : chaîne vide, pas d'erreur. Pour `${` sans `}`, `strchr` renvoie `NULL` : Minimake doit le traiter comme une erreur (non géré ici).

